import "../styles/about_styles.css";
import React, { Component } from "react";
import video from "/public/video/Avant-première.mp4"; //Attention, peut-être mettre un point quand je basculerais sur l'autre

class About_Video extends Component {
  render() {
    return (
      <div>
        <video
          src={video}
          className="fullscreen-video"
          autoPlay
          muted
          loop
        ></video>
      </div>
    );
  }
}

export function About() {
  return (
    <div>
      <h1> About </h1>
      <About_Video />
    </div>
  );
}
